//! Compares every case of `tests/data/bigint/corpus.txt` (generated by qjs, see
//! `tests/data/bigint/gen-corpus.js`) with `crate::bigint`.

extern crate std;

use super::*;
use std::format;
use std::string::{String, ToString};
use std::vec::Vec;

const CORPUS: &str = include_str!("../../../../tests/data/bigint/corpus.txt");

fn hex(s: &str) -> BigInt {
    let (neg, digits) = match s.strip_prefix('-') {
        Some(d) => (true, d),
        None => (false, s),
    };
    let b = BigInt::parse_digits(digits.bytes().map(u32::from), 16).expect("hex");
    BigInt::new(neg, b.mag)
}

fn show(b: &BigInt) -> String {
    b.to_string_radix(16)
}

fn shown(r: Result<BigInt>) -> String {
    match r {
        Ok(b) => show(&b),
        Err(Error::DivisionByZero | Error::NegativeExponent | Error::TooLarge) => {
            "!RangeError".to_string()
        }
        Err(Error::ExponentTooLarge) => "!RangeError".to_string(),
    }
}

fn f64_hex(h: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(h, 16).unwrap())
}

/// Decodes a JSON string literal (as JSON.stringify writes it) to UTF-16.
fn json_string(s: &str) -> Vec<u16> {
    let inner = &s[1..s.len() - 1];
    let mut out = Vec::new();
    let mut chars = inner.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            let mut buf = [0u16; 2];
            out.extend_from_slice(c.encode_utf16(&mut buf));
            continue;
        }
        match chars.next().unwrap() {
            'u' => {
                let h: String = chars.by_ref().take(4).collect();
                out.push(u16::from_str_radix(&h, 16).unwrap());
            }
            'n' => out.push(0x0A),
            't' => out.push(0x09),
            'r' => out.push(0x0D),
            'b' => out.push(0x08),
            'f' => out.push(0x0C),
            c => out.push(c as u16),
        }
    }
    out
}

fn ord(o: Option<Ordering>) -> &'static str {
    match o {
        None => "u",
        Some(Ordering::Less) => "-1",
        Some(Ordering::Equal) => "0",
        Some(Ordering::Greater) => "1",
    }
}

#[test]
fn qjs_corpus() {
    let mut failures = Vec::new();
    let mut n = 0;
    for line in CORPUS.lines() {
        let c: Vec<&str> = line.split('\t').collect();
        n += 1;
        let (want, got) = match c[0] {
            "add" | "sub" | "mul" | "div" | "mod" | "and" | "or" | "xor" | "shl" | "sar"
            | "pow" => {
                let (a, b) = (hex(c[1]), hex(c[2]));
                let r = match c[0] {
                    "add" => a.add(&b),
                    "sub" => a.sub(&b),
                    "mul" => a.mul(&b),
                    "div" => a.divrem(&b).map(|(q, _)| q),
                    "mod" => a.divrem(&b).map(|(_, r)| r),
                    "and" => Ok(a.and(&b)),
                    "or" => Ok(a.or(&b)),
                    "xor" => Ok(a.xor(&b)),
                    "shl" => a.shl(&b),
                    "sar" => a.shr(&b),
                    _ => a.pow(&b),
                };
                (c[3].to_string(), shown(r))
            }
            "cmp" => (
                c[3].to_string(),
                ord(Some(hex(c[1]).cmp(&hex(c[2])))).to_string(),
            ),
            "not" => (c[2].to_string(), shown(hex(c[1]).not())),
            "neg" => (c[2].to_string(), show(&hex(c[1]).neg())),
            "intn" | "uintn" => {
                let bits: u64 = c[1].parse().unwrap();
                let a = hex(c[2]);
                let r = if c[0] == "intn" {
                    a.as_int_n(bits)
                } else {
                    a.as_uint_n(bits)
                };
                (c[3].to_string(), shown(r))
            }
            "str" => {
                let radix: u32 = c[2].parse().unwrap();
                (
                    c[3].to_string(),
                    format!("\"{}\"", hex(c[1]).to_string_radix(radix)),
                )
            }
            "parse" => {
                let r = BigInt::parse_string(&json_string(c[1]));
                let got = r.map_or("!SyntaxError".to_string(), |b| show(&b));
                (c[2].to_string(), got)
            }
            "tonum" => {
                let f = hex(c[1]).to_f64();
                (c[2].to_string(), format!("{:016x}", f.to_bits()))
            }
            "fromnum" => {
                let f = f64_hex(c[1]);
                let got = if f.is_finite() && djs_libm::trunc(f) == f {
                    show(&BigInt::from_f64(f))
                } else {
                    "!RangeError".to_string()
                };
                (c[2].to_string(), got)
            }
            "cmpnum" => {
                let f = f64_hex(c[2]);
                (c[3].to_string(), ord(hex(c[1]).cmp_f64(f)).to_string())
            }
            op => panic!("unknown corpus op {op}"),
        };
        if want != got && failures.len() < 20 {
            failures.push(format!("{line}\n  got {got}"));
        }
    }
    assert!(n > 10000, "corpus too small: {n}");
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
